with valid as (select id, customer_id, plan, end_date, monthly_fee, status, dayofweek(start_date) as start_date_dayofweek from subscriptions where start_date >= to_date('2023-04-30') and customer_id is not null), scored as (select id, monthly_fee, lead(start_date_dayofweek) over w_recent as next_start_date_dayofweek, lag(start_date_dayofweek) over w_recent as prev_start_date_dayofweek, lead(monthly_fee) over w_recent as next_monthly_fee, row_number() over w_recent as row_seq, first_value(start_date_dayofweek) ignore nulls over (partition by customer_id, plan order by monthly_fee, id rows between unbounded preceding and current row) as first_known_start_date_dayofweek from valid window w_recent as (partition by status, plan order by monthly_fee, id)), with_windows as (select id, row_seq, first_known_start_date_dayofweek, sum(next_monthly_fee) over (order by row_seq, id rows between unbounded preceding and current row) as running_sum_next_monthly_fee, count(next_monthly_fee) over (order by row_seq, id rows between unbounded preceding and current row) as running_count_next_monthly_fee, min(next_monthly_fee) over (order by row_seq, id rows between unbounded preceding and current row) as running_min_next_monthly_fee, avg(next_monthly_fee) over (order by row_seq, id rows between unbounded preceding and current row) as running_avg_next_monthly_fee from scored where row_seq between 3 and 7), with_windows_subscriptions as (select id, first_known_start_date_dayofweek, running_sum_next_monthly_fee, running_count_next_monthly_fee, lead(running_avg_next_monthly_fee, 1) over w_recent as next_running_avg_next_monthly_fee, lag(first_known_start_date_dayofweek, 1) over w_grp as prev_first_known_start_date_dayofweek, ntile(3) over w_recent as running_sum_next_monthly_fee_bucket from with_windows window w_recent as (order by running_sum_next_monthly_fee, id), w_grp as (order by running_min_next_monthly_fee, id)), cleaned as (select id, first_known_start_date_dayofweek, running_sum_next_monthly_fee, next_running_avg_next_monthly_fee, ceil(prev_first_known_start_date_dayofweek) as prev_first_known_start_date_dayofweek_whole, ceil(prev_first_known_start_date_dayofweek) as prev_first_known_start_date_dayofweek_whole_2 from with_windows_subscriptions where running_count_next_monthly_fee >= 15), enriched as (select id, first_known_start_date_dayofweek, running_sum_next_monthly_fee, next_running_avg_next_monthly_fee, prev_first_known_start_date_dayofweek_whole_2, percent_rank() over w_hist as prev_first_known_start_date_dayofweek_whole_percent_rank, sum(prev_first_known_start_date_dayofweek_whole_2) over w_ordered as running_prev_first_known_start_date_dayofweek_whole_2 from cleaned window w_hist as (order by prev_first_known_start_date_dayofweek_whole), w_ordered as (order by prev_first_known_start_date_dayofweek_whole, id rows between unbounded preceding and current row)), enriched_subscriptions as (select *, avg(next_running_avg_next_monthly_fee) over (order by prev_first_known_start_date_dayofweek_whole_percent_rank, id rows between 5 preceding and 1 preceding) as next_running_avg_next_monthly_fee_avg_5_prior, avg(running_prev_first_known_start_date_dayofweek_whole_2) over (order by next_running_avg_next_monthly_fee, id rows between 5 preceding and current row) as running_prev_first_known_start_date_dayofweek_whole_2_avg_5, avg(running_prev_first_known_start_date_dayofweek_whole_2) over (order by prev_first_known_start_date_dayofweek_whole_2, id rows between 3 preceding and 1 preceding) as running_prev_first_known_start_date_dayofweek_whole_2_avg_3_prior from enriched), totals as (select case when first_known_start_date_dayofweek >= 89 then 'LARGE' else 'SMALL' end as first_known_start_date_dayofweek_tier, case when running_prev_first_known_start_date_dayofweek_whole_2 >= 350 then 'PREMIUM' else 'STANDARD' end as running_prev_first_known_start_date_dayofweek_whole_2_tier, min(running_prev_first_known_start_date_dayofweek_whole_2) as min_running_prev_first_known_start_date_dayofweek_whole_2, percentile_approx(prev_first_known_start_date_dayofweek_whole_percent_rank, array(0.25, 0.5, 0.75)) as prev_first_known_start_date_dayofweek_whole_percent_rank_quartiles, percentile_approx(prev_first_known_start_date_dayofweek_whole_2, 0.9) as prev_first_known_start_date_dayofweek_whole_2_p90 from enriched_subscriptions group by case when first_known_start_date_dayofweek >= 89 then 'LARGE' else 'SMALL' end, case when running_prev_first_known_start_date_dayofweek_whole_2 >= 350 then 'PREMIUM' else 'STANDARD' end) select first_known_start_date_dayofweek_tier, running_prev_first_known_start_date_dayofweek_whole_2_tier, min_running_prev_first_known_start_date_dayofweek_whole_2, prev_first_known_start_date_dayofweek_whole_percent_rank_quartiles from totals order by min_running_prev_first_known_start_date_dayofweek_whole_2 nulls first;
